package com.bank.portal.web; import com.bank.portal.service.BankingService; import com.bank.portal.web.ApiDtos.*; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/merchants") @RequiredArgsConstructor @PreAuthorize("hasRole('STAFF')") public class MerchantController {private final BankingService service; @GetMapping public List<MerchantView> all(){return service.merchantList();}@PostMapping public MerchantView create(@Valid @RequestBody MerchantRequest r){return service.createMerchant(r);}@PutMapping("/{id}") public MerchantView update(@PathVariable Long id,@Valid @RequestBody MerchantRequest r){return service.updateMerchant(id,r);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.deleteMerchant(id);}}
